const item = $input.first().json;
const md = item.data?.markdown ?? item.markdown ?? '';

const want = ['backend', 'node', 'mern', 'sde', 'software engineer', 'engineer', 'developer', 'devops', 'full stack', 'fullstack', 'intern', 'fresher', 'trainee'];
const skip = ['senior', 'lead', 'manager', 'principal', 'architect', 'sales'];

const re = /\[([^\]]+?)\\?<br>\\?<br>([^\]]+?)\]\((https?:\/\/[^)\s]+)\)/g;
const out = [];
let m;
while ((m = re.exec(md)) !== null) {
  const title = m[1].replace(/New$/, '').trim();
  const t = title.toLowerCase();
  if (want.some(w => t.includes(w)) && !skip.some(s => t.includes(s))) {
    out.push({ json: { title, location: m[2].trim(), link: m[3] } });
  }
}
return out;

const jobs = $input.all().map(i => i.json);
if (jobs.length === 0) return [];

const rows = jobs.map(j =>
  `<li><b>${j.title}</b> — ${j.company} (${j.location})<br><a href="${j.link}">Apply here</a></li>`
).join('');

return [{ json: {
  subject: `Job Hunter: ${jobs.length} matching job(s)`,
  html: `<ul>${rows}</ul>`
}}];
